package org.brightstats.desktop;
import java.util.*;import com.google.gson.*;import javafx.scene.canvas.*;import javafx.scene.layout.Region;import javafx.scene.control.Tooltip;import javafx.scene.input.*;import javafx.scene.paint.Color;import javafx.scene.text.Font;import org.brightstats.report.*;
/** Exact archived matrix cells; colours describe signed relative magnitude, not significance. */
final class MatrixHeatmap extends Region {
 final String title;final List<String> names;final double[][] values;final Canvas canvas=new Canvas();final Tooltip tooltip=new Tooltip();int row,column;double cell,left=170,top=145;double maximum;
 MatrixHeatmap(String title,List<String> names,double[][] matrix){this.title=title;this.names=List.copyOf(names);values=org.brightstats.stats.Matrices.copy(matrix);if(names.isEmpty()||names.size()>150||values.length!=names.size()||Arrays.stream(values).anyMatch(r->r.length!=names.size()))throw new IllegalArgumentException("Heatmaps require a square named matrix of 1–150 variables.");for(var line:values)for(double v:line)if(Double.isFinite(v))maximum=Math.max(maximum,Math.abs(v));getChildren().add(canvas);setFocusTraversable(true);setAccessibleText(title);setAccessibleHelp("Arrow keys inspect cells. Enter links both recorded variable columns. Colours show relative signed magnitude, not significance.");Tooltip.install(this,tooltip);setMinSize(530,470);setPrefSize(Math.max(680,170+names.size()*28),Math.max(520,170+names.size()*28));getProperties().put("brightstats.svg",(java.util.function.Supplier<String>)this::svg);getProperties().put("brightstats.redraw",(Runnable)this::draw);setOnMouseMoved(e->{int c=(int)Math.floor((e.getX()-left)/cell),r=(int)Math.floor((e.getY()-top)/cell);if(c>=0&&r>=0&&c<names.size()&&r<names.size()){row=r;column=c;describe();draw();}});setOnMouseClicked(e->{requestFocus();if(e.getX()>=left&&e.getY()>=top&&e.getX()<left+cell*names.size()&&e.getY()<top+cell*names.size())select();});setOnKeyPressed(e->{switch(e.getCode()){case LEFT->column=Math.max(0,column-1);case RIGHT->column=Math.min(names.size()-1,column+1);case UP->row=Math.max(0,row-1);case DOWN->row=Math.min(names.size()-1,row+1);case ENTER,SPACE->{select();e.consume();return;}default->{return;}}describe();draw();e.consume();});}
 void describe(){String text=names.get(row)+" × "+names.get(column)+": "+values[row][column];tooltip.setText(text);setAccessibleText(title+". "+text);}
 void select(){VisualSelection.publish(this,GraphicPoint.original(title+": "+names.get(row)+" × "+names.get(column),List.of(),new ArrayList<>(new LinkedHashSet<>(List.of(names.get(row),names.get(column))))));}
 Color color(double value){if(!Double.isFinite(value))return Color.web("#777777");double t=maximum==0?0:Math.min(1,Math.abs(value)/maximum);return Color.web("#f3f5f6").interpolate(Color.web(value<0?"#b64c32":"#176b93"),t);}
 @Override protected void layoutChildren(){canvas.setWidth(getWidth());canvas.setHeight(getHeight());cell=Math.max(1,Math.min((getWidth()-left-28)/names.size(),(getHeight()-top-45)/names.size()));draw();}
 void draw(){var g=canvas.getGraphicsContext2D();var palette=ModelDiagramGraphics.palette(UiAppearance.theme(),UiAppearance.current().accent());g.setFill(Color.web(palette.card()));g.fillRect(0,0,canvas.getWidth(),canvas.getHeight());g.setFont(Font.font(13));g.setFill(Color.web(palette.text()));g.fillText(title,12,23);g.setFont(Font.font(11));g.fillText("Signed relative magnitude; no significance threshold. Full cell values: hover / arrow keys.",12,44);for(int i=0;i<names.size();i++){g.setFill(Color.web(palette.text()));String label=names.get(i);if(label.length()>21)label=label.substring(0,20)+"…";g.fillText(label,8,top+(i+.5)*cell+4,155);g.save();g.translate(left+(i+.5)*cell,top-9);g.rotate(-55);g.fillText(label,0,0,135);g.restore();for(int j=0;j<names.size();j++){g.setFill(color(values[i][j]));g.fillRect(left+j*cell,top+i*cell,cell,cell);if(cell>=47){g.setFill(values[i][j]!=values[i][j]?Color.WHITE:luminance(color(values[i][j]))<.179?Color.WHITE:Color.BLACK);g.fillText(Double.isFinite(values[i][j])?String.format(Locale.ROOT,"%.3g",values[i][j]):"NA",left+j*cell+4,top+(i+.5)*cell+4,cell-7);}}}g.setStroke(Color.web(palette.text()));g.setLineWidth(2);g.strokeRect(left+column*cell+1,top+row*cell+1,Math.max(0,cell-2),Math.max(0,cell-2));}
 static double luminance(Color c){return .2126*linear(c.getRed())+.7152*linear(c.getGreen())+.0722*linear(c.getBlue());}
 static double linear(double v){return v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4);}
 String svg(){int n=names.size(),size=Math.max(26,Math.min(70,900/n)),width=210+n*size,height=190+n*size;StringBuilder s=new StringBuilder("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\""+width+"\" height=\""+height+"\" viewBox=\"0 0 "+width+" "+height+"\"><rect width=\"100%\" height=\"100%\" fill=\"white\"/><g font-family=\"sans-serif\" fill=\"#18364e\">");JsonObject source=new JsonObject();source.addProperty("format","bright-stats-matrix-graphic");source.addProperty("title",title);source.add("variables",new Gson().toJsonTree(names));source.add("matrix",matrixJson(values));s.append("<metadata>").append(XmlText.escape(source.toString())).append("</metadata><text x=\"12\" y=\"24\" font-size=\"16\">").append(XmlText.escape(title)).append("</text>");for(int i=0;i<n;i++){s.append("<text x=\"8\" y=\"").append(145+(i+.5)*size+4).append("\" font-size=\"11\">").append(XmlText.escape(shortName(names.get(i)))).append("</text><text transform=\"translate(").append(170+(i+.5)*size).append(" 136) rotate(-55)\" font-size=\"11\">").append(XmlText.escape(shortName(names.get(i)))).append("</text>");for(int j=0;j<n;j++){Color c=color(values[i][j]);s.append("<rect x=\"").append(170+j*size).append("\" y=\"").append(145+i*size).append("\" width=\"").append(size).append("\" height=\"").append(size).append("\" fill=\"").append(String.format(Locale.ROOT,"#%02x%02x%02x",Math.round(c.getRed()*255),Math.round(c.getGreen()*255),Math.round(c.getBlue()*255))).append("\"><title>").append(XmlText.escape(names.get(i)+" × "+names.get(j)+": "+values[i][j])).append("</title></rect>");}}return s.append("</g></svg>").toString();}
 private static JsonArray matrixJson(double[][] values){JsonArray matrix=new JsonArray();for(double[] line:values){JsonArray row=new JsonArray();for(double value:line)if(Double.isFinite(value))row.add(value);else row.add(JsonNull.INSTANCE);matrix.add(row);}return matrix;}
 private static String shortName(String s){return s.length()>21?s.substring(0,20)+"…":s;}
}
